#include <iostream>
#include <algorithm>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, dis, tcar, tw, ti;
    cin >> n >> dis >> tcar >> tw >> ti;

    if (n == 0) {
        cout << 0;
        return 0;
    }

    if (dis <= 0) {
        cout << n * tw;
        return 0;
    }

    const int64 taxiCost = tcar * dis;
    const int64 regularCost = taxiCost + ti;
    const int64 fullSegments = n / dis;
    const int64 remainder = n % dis;

    int64 nextCost = 0;

    if (fullSegments > 0) {
        if (remainder == 0) {
            if (fullSegments == 1) {
                nextCost = 0;
            } else {
                nextCost = min({
                    (fullSegments - 1) * regularCost,
                    (n - dis) * tw,
                    (fullSegments - 2) * regularCost + dis * tw
                });
            }
        } else {
            nextCost = min({
                (n - dis) * tw,
                (fullSegments - 1) * regularCost + remainder * tw,
                fullSegments * regularCost
            });
        }
    }

    cout << min(n * tw, taxiCost + nextCost);
    return 0;
}

#include <iostream>
#include <algorithm>
#include <string>
using namespace std;

using i128 = __int128_t;

void print(i128 value) {
    if (value == 0) {
        cout << 0;
        return;
    }
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string result;
    while (value > 0) {
        result.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n_, dis_, tcar_, tw_, ti_;
    cin >> n_ >> dis_ >> tcar_ >> tw_ >> ti_;

    i128 n = n_, dis = dis_, tcar = tcar_, tw = tw_, ti = ti_;

    if (n == 0) {
        cout << 0;
        return 0;
    }

    i128 q = n / dis;
    i128 r = (n % dis == 0 ? q - 1 : q);
    i128 firstRide = tcar * dis;
    i128 answer;

    if (r < 1) {
        answer = min(firstRide, n * tw);
    } else {
        i128 transition = ti + firstRide;
        i128 rideAll = r * transition;
        i128 walk;

        if (transition >= dis * tw) {
            walk = (n - dis) * tw;
        } else {
            walk = (r - 1) * transition + (n - r * dis) * tw;
        }

        i128 fromFirstStop = min(rideAll, walk);
        answer = min(firstRide + fromFirstStop, n * tw);
    }

    print(answer);
    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, dis, tcar, tw, ti;
    cin >> n >> dis >> tcar >> tw >> ti;

    if (n == 0) {
        cout << 0;
        return 0;
    }

    const long long stops = (n + dis - 1) / dis;
    const long long travelCost = tcar * dis;
    const long long stepCost = travelCost + ti;

    long long dp1 = 0;

    if (stops >= 2) {
        const long long driveToEnd = (stops - 1) * stepCost;
        long long switchToWalking;

        if (stepCost >= dis * tw) {
            switchToWalking = (n - dis) * tw;
        } else {
            switchToWalking =
                (stops - 2) * stepCost +
                (n - (stops - 1) * dis) * tw;
        }

        dp1 = min(driveToEnd, switchToWalking);
    }

    cout << min(n * tw, travelCost + dp1);
    return 0;
}

