int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, dis, tcar, tw, ti;
    cin >> n >> dis >> tcar >> tw >> ti;

    if (n <= 0) {
        cout << 0;
        return 0;
    }

    if (dis <= 0) {
        print((i128)n * tw);
        return 0;
    }

    long long segments = n / dis + (n % dis != 0);
    long long intermediate = segments - 1;

    i128 carCost = (i128)ti + (i128)tcar * dis;
    i128 dp1 = (i128)intermediate * carCost;

    if (intermediate > 0) {
        i128 walkAtFirst = (i128)(n - dis) * tw;
        i128 walkAtLast =
            (i128)(intermediate - 1) * carCost +
            ((i128)n - (i128)intermediate * dis) * tw;

        dp1 = min(dp1, min(walkAtFirst, walkAtLast));
    }

    i128 answer = min(dp1 + (i128)tcar * dis, (i128)n * tw);
    print(answer);
    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, dis, tcar, tw, ti;
    cin >> n >> dis >> tcar >> tw >> ti;

    if (n == 0) {
        cout << 0;
        return 0;
    }

    if (dis <= 0 || dis > n) {
        cout << min(n * tw, tcar * dis);
        return 0;
    }

    long long segments = n / dis;
    long long remainder = n % dis;
    long long carStep = ti + tcar * dis;

    long long dpAtFirst = (n - dis) * tw;
    dpAtFirst = min(dpAtFirst,
                    (segments - 1) * carStep + remainder * tw);

    if (remainder != 0)
        dpAtFirst = min(dpAtFirst, segments * carStep);

    cout << min(n * tw, tcar * dis + dpAtFirst);
    return 0;
}

